/* offline vfs guard (generated by the "vfs" converter) */
(function __omInstall() {
  var G = self;
  if (G.__OM_INSTALLED) return; G.__OM_INSTALLED = true;
  var VFS = G.__OM_VFS || {};            // relpath -> [mime, base64]
  var isWorker = typeof G.importScripts === 'function';
  var root = G.__OM_ROOT ||
    (G.location ? G.location.href.split('#')[0].split('?')[0].replace(/[^/]*$/, '') : '');
  G.__OM_ROOT = root;
  // Relative URLs resolve against the requesting scope: the document dir in the
  // window, the ORIGINAL script dir inside a rebuilt worker (its blob: URL
  // carries no path, so the Worker patch pins __OM_BASE at compose time).
  var base = G.__OM_BASE || root;
  var blobCache = {};

  function bytes(b64) {
    var bin = atob(b64), n = bin.length, a = new Uint8Array(n);
    for (var i = 0; i < n; i++) a[i] = bin.charCodeAt(i);
    return a;
  }
  // URL (string) -> {k[,native]} = in the VFS (native = a plain relative load
  // would also work), {miss:k} = local-but-ABSENT (the VFS embeds EVERY build
  // file, so a local miss provably does not exist — first-run save files,
  // drive-root junk), {ext:u} = external http(s), null = not ours (blob/data/
  // other schemes). Drive-root URLs (/gen_204 -> file:///C:/gen_204) are
  // re-tried as VFS keys so runtime-built root-absolute refs still resolve.
  function classify(u) {
    try {
      u = String(u);
      if (/^(blob:|data:|about:)/i.test(u)) return null;
      var abs = new URL(u, base).href;
      // Same-origin http(s) is the game's own server (e.g. localhost): those
      // files really exist, so leave them alone. Intercepting them breaks
      // boot — the Poki stub loader replaces ./poki2.js with an empty stub,
      // PokiSDK.init() never settles, and its dequeue() re-enqueues forever,
      // hanging the page on a black screen. The VFS stays a file:// fallback.
      try {
        var here = G.location && new URL(G.location.href);
        var dest = new URL(u, base);
        if (here && /^https?:$/i.test(dest.protocol) && dest.origin === here.origin) return null;
      } catch (e) {}
      if (/^https?:/i.test(abs)) return { ext: abs };
      abs = abs.split('#')[0].split('?')[0];
      if (abs.indexOf('file:') !== 0) return null;
      if (abs.indexOf(root) === 0) {
        var k = decodeURIComponent(abs.slice(root.length));
        return VFS[k] ? { k: k, native: true } : { miss: k };
      }
      var k2 = decodeURIComponent(abs.replace(/^file:\/\/\/([A-Za-z]:\/)?/, ''));
      return VFS[k2] ? { k: k2 } : { miss: k2 };
    } catch (e) { return null; }
  }
  function keyFor(u) { var c = classify(u); return (c && c.k) || null; }
  // Provably-absent local file: answer like the original web server did (a
  // quiet 404) instead of letting file:// spray ERR_FILE_NOT_FOUND console
  // errors for expected-absent files (save data on first run).
  function log404(k) { if (G.console) console.info('[vfs] 404 (absent from VFS): ' + k); }
  // Engine boilerplate alerts that fire BECAUSE we're on file: (e.g. every
  // Construct 3 export warns "browsers block many features" — features this
  // guard exists to unblock). The warning is factually wrong for a vfs build
  // and, worse, a native dialog blocks the renderer. Registry of known
  // false-alarm patterns; anything else still alerts normally.
  var FALSE_ALARMS = [
    /file: protocol|upload them/i,                    // Construct 3
    /not a web server is not advised/i,               // GameMaker HTML5
  ];
  if (!isWorker && G.alert) {
    var oAlert = G.alert.bind(G);
    G.alert = function (msg) {
      for (var i = 0; i < FALSE_ALARMS.length; i++) {
        if (FALSE_ALARMS[i].test(String(msg))) {
          return void (G.console && console.info('[vfs] suppressed offline false-alarm alert: ' + msg));
        }
      }
      return oAlert(msg);
    };
  }

  function blobFor(k) { return new Blob([bytes(VFS[k][1])], { type: VFS[k][0] }); }
  function blobUrlFor(k) { return blobCache[k] || (blobCache[k] = URL.createObjectURL(blobFor(k))); }
  function textFor(k) { return new TextDecoder().decode(bytes(VFS[k][1])); }

  // fetch: serve from the VFS (a Response with the right MIME also satisfies
  // WebAssembly.instantiateStreaming). Non-VFS URLs pass through untouched.
  var oFetch = G.fetch && G.fetch.bind(G);
  if (oFetch) G.fetch = function (input, init) {
    var u = input && input.url !== undefined ? input.url : input;
    var c = classify(u);
    if (c && c.k) return Promise.resolve(new Response(blobFor(c.k), {
      status: 200, headers: { 'Content-Type': VFS[c.k][0] },
    }));
    if (c && (c.miss !== undefined || c.ext)) {
      log404(c.miss !== undefined ? c.miss : c.ext);
      return Promise.resolve(new Response('', { status: 404, statusText: 'Not Found' }));
    }
    return oFetch(input, init);
  };

  // XHR: reroute the URL to a blob: copy — works over file://, any responseType.
  // A local miss never touches the network: send() synthesizes a quiet 404.
  if (G.XMLHttpRequest) {
    var XP = G.XMLHttpRequest.prototype, oOpen = XP.open, oSend = XP.send;
    XP.open = function (m, u) {
      var c = classify(u);
      this.__om404 = c ? (c.miss !== undefined ? c.miss : (c.ext || null)) : null;
      if (c && c.k) arguments[1] = blobUrlFor(c.k);
      else if (this.__om404 !== null) arguments[1] = 'data:,'; // placeholder, never sent
      return oOpen.apply(this, arguments);
    };
    XP.send = function () {
      if (this.__om404 === null || this.__om404 === undefined) return oSend.apply(this, arguments);
      var x = this, text = x.responseType === '' || x.responseType === 'text';
      log404(x.__om404);
      setTimeout(function () {
        try {
          Object.defineProperty(x, 'readyState', { value: 4, configurable: true });
          Object.defineProperty(x, 'status', { value: 404, configurable: true });
          Object.defineProperty(x, 'statusText', { value: 'Not Found', configurable: true });
          Object.defineProperty(x, 'response', { value: text ? '' : null, configurable: true });
          if (text) Object.defineProperty(x, 'responseText', { value: '', configurable: true });
        } catch (e) {}
        x.dispatchEvent(new Event('readystatechange'));
        x.dispatchEvent(new ProgressEvent('load'));
        x.dispatchEvent(new ProgressEvent('loadend'));
      }, 0);
    };
  }

  // Runtime-built element srcs (script/img/media): THEORY's src-setter channel.
  // Games compose these at runtime (Google's /gen_204 pings, lazy xjs scripts,
  // GameMaker's lazy texture loads) so build-time rebase never sees them.
  // Policy: script native-resolvable hit -> untouched (preserves
  // document.currentScript); img/media hit -> blob: ALWAYS (naked file:// +
  // crossOrigin = hard CORS fail, and plain file:// taints the canvas);
  // provably-dead local or external -> inert data: stub, so nothing 404s and
  // nothing escapes. crossOrigin itself is swallowed below.
  if (!isWorker && G.HTMLScriptElement && G.Object) {
    var INERT_IMG = 'data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7';
    // Scripts that must FAIL (fire 'error') instead of loading empty:
    //  (a) provably-absent LOCAL scripts — a static host answers 404 and the
    //      browser fires onerror, and that failure can be LOAD-BEARING: poki's
    //      boot is Promise.all([...script loads]).catch(-> dispatch adblocked)
    //      .then(n => n !== undefined && buildAdManager()). The 3kh0 rip
    //      deliberately lacks ./prebid4.12.0.js (+ blanks the ad URLs) so the
    //      reject IS how the game runs ad-free on 3kh0's own host. Our old
    //      empty-success stub made poki think ads loaded -> new google.ima.*
    //      -> 'google is not defined' -> black screen (stickman-hook).
    //  (b) known ad-SDK HOSTS (registry, not hardcoding) — every ad SDK ships
    //      an adblocked path; a failed load is its designed-for offline state.
    // Other external scripts keep the empty-success stub (conservative: a lib
    // stub crashes either way, and inline vendors real CDN libs at build time).
    // Markup-channel scripts (document.write) keep the old stub — no element
    // to dispatch on at string-rewrite time (recorded asymmetry).
    var FAIL_SCRIPT_HOSTS = [
      /(^|\.)imasdk\.googleapis\.com$/i,
      /(^|\.)doubleclick\.net$/i,
      /(^|\.)googlesyndication\.com$/i,
    ];
    var shouldFailScript = function (c) {
      if (c.miss !== undefined) return true;
      if (c.ext) {
        try {
          var h = new URL(c.ext).hostname;
          for (var i = 0; i < FAIL_SCRIPT_HOSTS.length; i++) {
            if (FAIL_SCRIPT_HOSTS[i].test(h)) return true;
          }
        } catch (e) {}
      }
      return false;
    };
    var FAIL = {}; // sentinel: caller must NOT set the underlying src
    var failScript = function (el, u) {
      if (G.console) console.info('[vfs] script load failed on purpose (absent/ad-sdk): ' + u);
      setTimeout(function () {
        try { el.dispatchEvent(new Event('error')); } catch (e) {}
      }, 0); // async: onerror is usually assigned AFTER src= (loader idiom)
      return FAIL;
    };
    var mapSrc = function (el, v) {
      var c = classify(v);
      if (!c) return v;
      var t = (el.tagName || '').toLowerCase();
      if (c.k) {
        // script: a native-resolvable hit stays untouched (document.currentScript).
        // img/media: ALWAYS a blob: copy — over naked file:// a crossOrigin
        // load hard-fails CORS (origin 'null') and even a plain load taints
        // the canvas, so pixel-reading engines (GameMaker textures) break
        // either way; a same-origin blob: does neither. Covers lazy loads at
        // ANY depth in the game, not just boot.
        return (t === 'script' && c.native) ? v : blobUrlFor(c.k);
      }
      log404(c.miss !== undefined ? c.miss : c.ext);
      if (t === 'script' && shouldFailScript(c)) {
        return failScript(el, c.miss !== undefined ? c.miss : c.ext);
      }
      return t === 'script' ? 'data:text/javascript,' : t === 'img' ? INERT_IMG : 'data:,';
    };
    // NOTE: in real browsers 'src' is an OWN accessor of HTMLMediaElement.prototype
    // (audio/video only inherit it) — patch the owner or the media patch is a no-op.
    [G.HTMLScriptElement, G.HTMLImageElement, G.HTMLMediaElement, G.HTMLAudioElement, G.HTMLVideoElement, G.HTMLSourceElement]
      .forEach(function (C) {
        if (!C) return;
        var d = Object.getOwnPropertyDescriptor(C.prototype, 'src');
        if (!d || !d.set) return;
        Object.defineProperty(C.prototype, 'src', {
          get: d.get, configurable: true,
          set: function (v) {
            var m = mapSrc(this, v);
            if (m !== FAIL) d.set.call(this, m); // FAIL: no load starts; only the error event fires
          },
        });
      });
    // crossOrigin is a guaranteed CORS failure over file:// (origin 'null')
    // and pointless offline: VFS media is served as same-origin blob: copies
    // that never taint the canvas, and external refs are stubbed. Swallow the
    // setter (value stays readable on the element) so engines that set
    // img.crossOrigin='anonymous' before src (GameMaker) don't kill their
    // own texture loads.
    [G.HTMLImageElement, G.HTMLMediaElement, G.HTMLScriptElement, G.HTMLLinkElement]
      .forEach(function (C) {
        if (!C) return;
        var d = Object.getOwnPropertyDescriptor(C.prototype, 'crossOrigin');
        if (!d || !d.set) return;
        Object.defineProperty(C.prototype, 'crossOrigin', {
          configurable: true,
          get: function () { return this.__omXO !== undefined ? this.__omXO : null; },
          set: function (v) { this.__omXO = v; },
        });
      });
    var XO_TAGS = /^(img|audio|video|source|script|link)$/;
    var oSetAttr = G.Element && G.Element.prototype.setAttribute;
    if (oSetAttr) G.Element.prototype.setAttribute = function (n, v) {
      var ln = String(n).toLowerCase();
      if (ln === 'crossorigin' && XO_TAGS.test((this.tagName || '').toLowerCase())) {
        this.__omXO = v;
        return;
      }
      if (ln === 'src') {
        v = mapSrc(this, v);
        if (v === FAIL) return; // no attribute set; only the error event fires
      }
      return oSetAttr.call(this, n, v);
    };
  }

  // Runtime CSS url() channel (THEORY Part 3). Games set url()-bearing props at
  // runtime — e.g. el.style.backgroundImage = 'url(logo.png)'. The CSS engine
  // resolves that against the document base with NO element src setter to catch
  // it, so over file:// a VFS asset can't load and an absent one 404s. Rewrite
  // every url() token: VFS hit -> blob: (loads + never taints), provably-absent
  // local OR external -> transparent 1px (cosmetic; nothing 404s, nothing
  // escapes). Covers setProperty, cssText, and the named camelCase accessors.
  if (!isWorker && G.CSSStyleDeclaration && G.Object) {
    var CLEAR_PX = 'data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7';
    var mapCss = function (v) {
      if (typeof v !== 'string' || v.indexOf('url(') === -1) return v;
      return v.replace(/url\(\s*(['"]?)([^'")]+)\1\s*\)/gi, function (m, q, u) {
        if (/^(blob:|data:|about:)/i.test(u)) return m;
        var c = classify(u);
        if (c && c.k) return 'url("' + blobUrlFor(c.k) + '")';
        if (c && (c.miss !== undefined || c.ext)) return 'url("' + CLEAR_PX + '")';
        return m;
      });
    };
    var CSP = G.CSSStyleDeclaration.prototype;
    var oSetProp = CSP.setProperty;
    if (oSetProp) CSP.setProperty = function (n, val, pr) { return oSetProp.call(this, n, mapCss(val), pr); };
    var dText = Object.getOwnPropertyDescriptor(CSP, 'cssText');
    if (dText && dText.set) Object.defineProperty(CSP, 'cssText', {
      get: dText.get, configurable: true,
      set: function (v) { dText.set.call(this, mapCss(v)); },
    });
    // el.style.backgroundImage = ... routes through a named accessor. Chrome
    // exposes these on the prototype (wrap it); if an engine hides it behind a
    // native named-property handler, back our accessor with the (already
    // patched) setProperty/getPropertyValue store.
    ['background', 'backgroundImage', 'borderImage', 'borderImageSource',
     'listStyleImage', 'maskImage', 'webkitMaskImage', 'cursor', 'content']
      .forEach(function (prop) {
        var d = Object.getOwnPropertyDescriptor(CSP, prop);
        if (d && d.set && d.get) {
          Object.defineProperty(CSP, prop, {
            get: d.get, configurable: true, enumerable: d.enumerable,
            set: function (v) { d.set.call(this, mapCss(v)); },
          });
        } else {
          var css = prop.replace(/^webkit/, 'webkit-').replace(/[A-Z]/g, function (c) { return '-' + c.toLowerCase(); });
          if (css.indexOf('webkit-') === 0) css = '-' + css;
          Object.defineProperty(CSP, prop, {
            configurable: true,
            get: function () { return this.getPropertyValue(css); },
            set: function (v) { this.setProperty(css, v); },
          });
        }
      });
  }

  // Markup-injection channel (THEORY Part 3 "innerHTML-born elements").
  // Parser-created elements never hit the src SETTERS above — the request
  // fires during parse, e.g. poki's SDK spinner:
  //   spinnerContainer.innerHTML = '...<img src="https://game-cdn.poki.com/...svg">...'
  // So rewrite the MARKUP STRING before the parser sees it. Coverage: src=""
  // on loadable tags (native VFS hit -> untouched, non-native hit -> blob:,
  // dead/external -> inert stub per tag), stylesheet <link href>, url() in
  // style="" attributes (entity-escaped so mapCss's quotes can't break the
  // attribute) and in <style> blocks. Patched entry points: innerHTML,
  // outerHTML, insertAdjacentHTML, document.write/writeln. Quoted attributes
  // only (unquoted src= in an injected string is vanishingly rare — recorded).
  if (!isWorker && G.Element && typeof mapCss === 'function' && typeof classify === 'function') {
    var mapUrlAttr = function (u, t) {
      var c = classify(u);
      if (!c) return u;
      // Same policy as the src-setter channel: script native hit untouched
      // (document.currentScript), img/media hit ALWAYS blob: (plain file://
      // taints the canvas, crossOrigin hard-fails CORS).
      if (c.k) return (t === 'script' && c.native) ? u : blobUrlFor(c.k);
      log404(c.miss !== undefined ? c.miss : c.ext);
      return t === 'script' ? 'data:text/javascript,' : t === 'img' ? INERT_IMG : 'data:,';
    };
    var escAttr = function (v, q) { return v.split(q).join(q === '"' ? '&quot;' : '&#39;'); };
    var SRC_TAGS = /^(img|script|audio|video|source|iframe|embed|track|input)$/;
    var mapMarkup = function (html) {
      if (typeof html !== 'string' || html.indexOf('<') === -1) return html;
      return html
        .replace(/<(\w+)([^>]*)>/g, function (m, tag, attrs) {
          var t = tag.toLowerCase();
          if (SRC_TAGS.test(t)) {
            attrs = attrs.replace(/(\ssrc\s*=\s*(["']))([^"']*)\2/gi,
              function (a, pre, q, u) { return pre + mapUrlAttr(u, t) + q; });
          }
          if (t === 'link') {
            attrs = attrs.replace(/(\shref\s*=\s*(["']))([^"']*)\2/gi,
              function (a, pre, q, u) {
                var c = classify(u);
                if (!c) return a;
                // link stylesheet VFS hit -> blob: always (a file:// link
                // sheet is foreign-origin: cssRules throws).
                if (c.k) return pre + blobUrlFor(c.k) + q;
                log404(c.miss !== undefined ? c.miss : c.ext);
                return pre + 'data:,' + q;
              });
          }
          attrs = attrs.replace(/(\sstyle\s*=\s*(["']))([^"']*)\2/gi,
            function (a, pre, q, v) { return pre + escAttr(mapCss(v), q) + q; });
          return '<' + tag + attrs + '>';
        })
        .replace(/(<style\b[^>]*>)([\s\S]*?)(<\/style)/gi,
          function (m, open, css, close) { return open + mapCss(css) + close; });
    };
    var EP = G.Element.prototype;
    var dIH = Object.getOwnPropertyDescriptor(EP, 'innerHTML');
    if (dIH && dIH.set) Object.defineProperty(EP, 'innerHTML', {
      get: dIH.get, configurable: true,
      set: function (v) {
        dIH.set.call(this, this.tagName === 'STYLE' ? mapCss(String(v)) : mapMarkup(v));
      },
    });
    var dOH = Object.getOwnPropertyDescriptor(EP, 'outerHTML');
    if (dOH && dOH.set) Object.defineProperty(EP, 'outerHTML', {
      get: dOH.get, configurable: true,
      set: function (v) { dOH.set.call(this, mapMarkup(v)); },
    });
    var oIAH = EP.insertAdjacentHTML;
    if (oIAH) EP.insertAdjacentHTML = function (pos, html) {
      return oIAH.call(this, pos, mapMarkup(html));
    };
    var DocP = G.Document && G.Document.prototype;
    ['write', 'writeln'].forEach(function (fn) {
      if (!DocP || !DocP[fn]) return;
      var o = DocP[fn];
      DocP[fn] = function () {
        var args = Array.prototype.slice.call(arguments).map(mapMarkup);
        return o.apply(this, args);
      };
    });
    // <style>-element TEXT channel (fireboy's GD branding:
    // d.appendChild(document.createTextNode(cssString)) with a url() inside).
    // CSS arriving as a text node crosses neither innerHTML nor the CSSOM
    // setters — rewrite it at insertion / assignment.
    var NP = G.Node && G.Node.prototype;
    var styleText = function (parent, child) {
      if (parent && parent.tagName === 'STYLE' && child && child.nodeType === 3 && child.data) {
        try { child.data = mapCss(child.data); } catch (e) {}
      }
      return child;
    };
    if (NP && NP.appendChild) {
      var oAppend = NP.appendChild;
      NP.appendChild = function (child) { return oAppend.call(this, styleText(this, child)); };
      var oInsB = NP.insertBefore;
      if (oInsB) NP.insertBefore = function (child, ref) { return oInsB.call(this, styleText(this, child), ref); };
      var dTC = Object.getOwnPropertyDescriptor(NP, 'textContent');
      if (dTC && dTC.set) Object.defineProperty(NP, 'textContent', {
        get: dTC.get, configurable: true,
        set: function (v) {
          dTC.set.call(this, this.tagName === 'STYLE' && typeof v === 'string' ? mapCss(v) : v);
        },
      });
    }
  }

  // Beacons are telemetry by definition — swallow them all, never escape.
  if (G.navigator && G.navigator.sendBeacon) {
    G.navigator.sendBeacon = function (u) {
      if (G.console) console.info('[vfs] swallowed beacon: ' + u);
      return true;
    };
  }

  // Worker: new Worker(file://...) throws over file://. Rebuild the worker from
  // its VFS source with the whole guard (VFS + root + installer) prepended, so
  // the interceptors are live inside the worker before its first statement.
  if (G.Worker) {
    var OW = G.Worker;
    G.Worker = function (u, opts) {
      var k = (typeof u === 'string' || u instanceof URL) ? keyFor(u) : null;
      if (!k) return new OW(u, opts);
      var src = 'self.__OM_VFS=' + JSON.stringify(VFS) +
        ';self.__OM_ROOT=' + JSON.stringify(root) +
        ';self.__OM_BASE=' + JSON.stringify(new URL(k, root).href.replace(/[^/]*$/, '')) +
        ';(' + __omInstall.toString() + ')();\n' + textFor(k);
      return new OW(URL.createObjectURL(new Blob([src], { type: 'text/javascript' })), opts);
    };
    G.Worker.prototype = OW.prototype;
  }

  // importScripts (worker scope): relative/file URLs can't load in a blob
  // worker — serve blob: copies from the VFS instead.
  if (isWorker) {
    var oImp = G.importScripts.bind(G);
    G.importScripts = function () {
      var args = Array.prototype.slice.call(arguments).map(function (u) {
        var k = keyFor(u);
        return k ? blobUrlFor(k) : u;
      });
      return oImp.apply(null, args);
    };
  }
})();
